import type { Config } from '../lib/types.js';

// The configuration surface, in one table.
//
// Everything derives from `CONFIG_FIELDS`: validation, the environment mapping,
// the redaction list and `docs/configuration.md` (generated by
// `npm run gen:config-docs`, checked by `npm run check:config-docs`). Adding a
// setting means adding a row here and nothing else — a documented key that the
// code ignores, or an env var that nothing reads, cannot exist.

export type FieldKind =
  'string' | 'port' | 'positive-int' | 'non-negative-int' | 'enum' | 'string-list' | 'string-map';

export interface FieldDefinition {
  /** Dotted path in the config object. */
  path: string;
  kind: FieldKind;
  /** Value used when neither the file nor the environment supplies one. */
  defaultValue?: unknown;
  /** Allowed values for `enum`. */
  values?: readonly string[];
  /** Canonical environment variable: `HASTE_` + path, `__` between segments. */
  env: string;
  /** Historical variable names still honoured, lowest precedence. */
  legacyEnv?: readonly string[];
  /** Never printed: masked in logs and in the generated documentation. */
  secret?: boolean;
  /** One line for the generated documentation. */
  summary: string;
  example?: string;
}

/**
 * Canonical environment name for a config path: segments split on '.', joined
 * with '__', camelCase split into words, everything upper-cased.
 *
 *   storage.type                      -> HASTE_STORAGE__TYPE
 *   rateLimits.categories.normal.every -> HASTE_RATE_LIMITS__CATEGORIES__NORMAL__EVERY
 */
export const envName = (path: string): string =>
  'HASTE_' +
  path
    .split('.')
    .map((segment) => segment.replace(/([a-z0-9])([A-Z])/g, '$1_$2').toUpperCase())
    .join('__');

