export const FIELD_BY_PATH: ReadonlyMap<string, FieldDefinition> = new Map(
  CONFIG_FIELDS.map((field) => [field.path, field])
);

/** Every environment variable the server reads, canonical names first. */
export const ENV_NAMES: readonly string[] = CONFIG_FIELDS.flatMap((field) => [
  field.env,
  ...(field.legacyEnv ?? [])
]);

/** Path of the config file itself. */
export const CONFIG_PATH_ENV = 'HASTE_CONFIG';
/** Set to `1`/`true` to force SOPS decryption of the config file. */
export const SOPS_ENV = 'HASTE_CONFIG_SOPS';
/** Set to `1`/`true` to skip SOPS detection entirely. */
export const NO_SOPS_ENV = 'HASTE_CONFIG_NO_SOPS';

export const DEFAULTS: Readonly<Record<string, unknown>> = Object.fromEntries(
  CONFIG_FIELDS.filter((field) => field.defaultValue !== undefined).map((field) => [
    field.path,
    field.defaultValue
  ])
);

export type ConfigSource = 'default' | 'file' | 'env' | 'secret-file';

export interface ResolvedConfig {
  config: Config;
  /** Where each dotted path got its value. */
  sources: Readonly<Record<string, ConfigSource>>;
  /** The file that was read, or null when the file layer was skipped. */
  configPath: string | null;
  /** True when the file layer was decrypted with SOPS. */
  decrypted: boolean;
}
